import React, {
    useRef,
    useState,
    useEffect
} from 'react'

import {
    Text,
    Animated,
    TouchableOpacity,
    View
} from 'react-native'

import { useContexState } from '../../../hooks/context';
import { styles } from './styles'

export function Alert() {
    const [active, setActive] = useState(false);
    const fadeAnim = useRef(new Animated.Value(0)).current;

    const {
        alertMessage,
        alertActive
    } = useContexState();

    const {
        setAlertActive,
    } = useContexState();


    function AnimatedAlert(value: boolean) {
        setActive(true);
        Animated.timing(fadeAnim, {
            toValue: value ? 1 : 0,
            duration: 700,
        } as Animated.TimingAnimationConfig).start(() => {
            if (!value) {
                setActive(false)
            };
        });
    };


    useEffect(() => {
        AnimatedAlert(alertActive);
    }, [alertActive]);


    const qwe = true ? 'Aprovado' : 'Em análise';

    const Asd = (
        <Text style={{ fontSize: 18 }}>
            <View>Nome{'\n'}{'Fabio Moraes'}{'\n'}</View>
            <View>{'\n'}Telefone{'\n'}{'(018)998134187'}{'\n'}</View>
            <View>{'\n'}Situação{'\n'}{qwe}{'\n'}</View>
            <View>{'\n'}Revendedor{'\n'}{'Nenhum'}{'\n'}</View>
            <View>{'\n'}Momento{'\n'}{'2022-01-31T02:56:07.000Z'}{'\n'}</View>
            <View>{'\n'}Preço{'\n'}{'R$ 19,90'}</View>
        </ Text >
    );


    return !active ? <>
        <TouchableOpacity
            onPress={() => setAlertActive(false)}
            style={styles.containeMain} />
        <Animated.View style={[styles.container/*, { opacity: fadeAnim }*/]} >
            <Text style={styles.listText}>{/*alertMessage*/ Asd}</Text>
        </Animated.View>
    </> : <View />
};
